    "content": "{\"plan_id\":\"P-E1\",\"decision\":\"proceed\",\"reason\":null,\"status\":\"rolled_back\",\"drift\":[],\"affected_components\":[\"api\"],\"rollback_count\":1,\"final_state\":{\"api\":\"v1\"}}\n"
